object Solution {
  def maxDistance(nums1: Array[Int], nums2: Array[Int]): Int = {
    def binarySearch(target: Int, low: Int, high: Int): Int = {
      if (low > high) return -1

      val mid = low + (high - low) / 2
      if (nums2(mid) <= target) {
        if (mid == nums2.length - 1 || nums2(mid + 1) > target) return mid
